CREATE TYPE "APIApplicationStatus" AS ENUM ('ACTIVE','SUSPENDED','REVOKED'); CREATE TYPE "WebhookEndpointStatus" AS ENUM ('ACTIVE','PAUSED','REVOKED'); CREATE TYPE "WebhookDeliveryStatusV1" AS ENUM ('PENDING','RETRYING','DELIVERED','FAILED');
CREATE TABLE "APIApplication" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"name" TEXT NOT NULL,"status" "APIApplicationStatus" NOT NULL DEFAULT 'ACTIVE',"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE,FOREIGN KEY("createdBy") REFERENCES "User"("id") ON DELETE RESTRICT);
CREATE TABLE "APIClient" ("id" TEXT PRIMARY KEY,"applicationId" TEXT NOT NULL,"name" TEXT NOT NULL,"status" "APIApplicationStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,FOREIGN KEY("applicationId") REFERENCES "APIApplication"("id") ON DELETE CASCADE);
CREATE TABLE "APICredential" ("id" TEXT PRIMARY KEY,"clientId" TEXT NOT NULL,"keyId" TEXT NOT NULL UNIQUE,"secretHash" TEXT NOT NULL,"fingerprint" TEXT NOT NULL,"expiresAt" TIMESTAMP(3),"revokedAt" TIMESTAMP(3),"lastUsedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("clientId") REFERENCES "APIClient"("id") ON DELETE CASCADE);
CREATE TABLE "APIGrant" ("id" TEXT PRIMARY KEY,"applicationId" TEXT NOT NULL,"scope" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("applicationId") REFERENCES "APIApplication"("id") ON DELETE CASCADE);
CREATE TABLE "WebhookEndpoint" ("id" TEXT PRIMARY KEY,"applicationId" TEXT NOT NULL,"businessId" TEXT NOT NULL,"url" TEXT NOT NULL,"events" TEXT[] NOT NULL,"secretHash" TEXT NOT NULL,"secretCiphertext" TEXT NOT NULL,"secretIv" TEXT NOT NULL,"secretTag" TEXT NOT NULL,"status" "WebhookEndpointStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,FOREIGN KEY("applicationId") REFERENCES "APIApplication"("id") ON DELETE CASCADE,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE);
CREATE TABLE "WebhookDelivery" ("id" TEXT PRIMARY KEY,"endpointId" TEXT NOT NULL,"eventId" TEXT NOT NULL UNIQUE,"eventType" TEXT NOT NULL,"eventVersion" INTEGER NOT NULL,"payload" JSONB NOT NULL,"status" "WebhookDeliveryStatusV1" NOT NULL DEFAULT 'PENDING',"nextAttemptAt" TIMESTAMP(3) NOT NULL,"deliveredAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("endpointId") REFERENCES "WebhookEndpoint"("id") ON DELETE CASCADE);
CREATE TABLE "WebhookAttempt" ("id" TEXT PRIMARY KEY,"deliveryId" TEXT NOT NULL,"attemptNumber" INTEGER NOT NULL,"statusCode" INTEGER,"errorCode" TEXT,"attemptedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("deliveryId") REFERENCES "WebhookDelivery"("id") ON DELETE CASCADE);
CREATE TABLE "APIUsageRecord" ("id" TEXT PRIMARY KEY,"applicationId" TEXT NOT NULL,"clientId" TEXT NOT NULL,"businessId" TEXT NOT NULL,"operation" TEXT NOT NULL,"statusCode" INTEGER NOT NULL,"latencyMs" INTEGER NOT NULL,"requestId" TEXT NOT NULL,"occurredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("applicationId") REFERENCES "APIApplication"("id") ON DELETE CASCADE,FOREIGN KEY("clientId") REFERENCES "APIClient"("id") ON DELETE CASCADE,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE);
CREATE TABLE "APIRateLimitBucket" ("id" TEXT PRIMARY KEY,"clientId" TEXT NOT NULL,"businessId" TEXT NOT NULL,"operation" TEXT NOT NULL,"windowStart" TIMESTAMP(3) NOT NULL,"count" INTEGER NOT NULL DEFAULT 0,"expiresAt" TIMESTAMP(3) NOT NULL,FOREIGN KEY("clientId") REFERENCES "APIClient"("id") ON DELETE CASCADE,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "APIApplication_businessId_name_key" ON "APIApplication"("businessId","name"); CREATE INDEX "APIApplication_businessId_status_idx" ON "APIApplication"("businessId","status"); CREATE UNIQUE INDEX "APIClient_applicationId_name_key" ON "APIClient"("applicationId","name"); CREATE INDEX "APICredential_clientId_revokedAt_expiresAt_idx" ON "APICredential"("clientId","revokedAt","expiresAt"); CREATE UNIQUE INDEX "APIGrant_applicationId_scope_key" ON "APIGrant"("applicationId","scope"); CREATE INDEX "WebhookEndpoint_businessId_status_idx" ON "WebhookEndpoint"("businessId","status"); CREATE INDEX "WebhookDelivery_endpointId_status_nextAttemptAt_idx" ON "WebhookDelivery"("endpointId","status","nextAttemptAt"); CREATE UNIQUE INDEX "WebhookAttempt_deliveryId_attemptNumber_key" ON "WebhookAttempt"("deliveryId","attemptNumber"); CREATE INDEX "APIUsageRecord_businessId_occurredAt_idx" ON "APIUsageRecord"("businessId","occurredAt"); CREATE INDEX "APIUsageRecord_clientId_operation_occurredAt_idx" ON "APIUsageRecord"("clientId","operation","occurredAt"); CREATE UNIQUE INDEX "APIRateLimitBucket_clientId_businessId_operation_windowStart_key" ON "APIRateLimitBucket"("clientId","businessId","operation","windowStart"); CREATE INDEX "APIRateLimitBucket_expiresAt_idx" ON "APIRateLimitBucket"("expiresAt");
